import{_ as a,o as n,c as e,ai as i}from"./chunks/framework.Ba-VnP44.js";const h=JSON.parse('{"title":"Git 与版本管理","description":"","frontmatter":{},"headers":[],"relativePath":"ai/productivity/dev-spec/03-quality/git-version.md","filePath":"ai/productivity/dev-spec/03-quality/git-version.md"}'),l={name:"ai/productivity/dev-spec/03-quality/git-version.md"};function p(r,s,t,c,d,o){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="git-与版本管理" tabindex="-1">Git 与版本管理 <a class="header-anchor" href="#git-与版本管理" aria-label="Permalink to “Git 与版本管理”">​</a></h1><blockquote><p>第三层 · 质量保障。解决「怎么保护已有改动、让每次变更可追溯」——Git 是项目资产的安全底线，AI 改动最容易在这里出事。</p></blockquote><h2 id="贯穿全流程的定位" tabindex="-1">贯穿全流程的定位 <a class="header-anchor" href="#贯穿全流程的定位" aria-label="Permalink to “贯穿全流程的定位”">​</a></h2><p>Git 检查在每个产生改动的环节都要做，尤其是每轮开发提交前和最终交付前。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to “核心内容”">​</a></h2><h3 id="提交前的硬规矩" tabindex="-1">提交前的硬规矩 <a class="header-anchor" href="#提交前的硬规矩" aria-label="Permalink to “提交前的硬规矩”">​</a></h3><ul><li><strong>先看 <code>git status</code></strong>，识别用户已有的修改、未跟踪文件、暂存区内容。</li><li><strong>不覆盖用户已有改动</strong>：AI 的改动和用户改动在同一文件时，停下来说明，不擅自 <code>checkout --</code>、<code>reset --hard</code>、<code>stash</code> 或强行合并。</li><li>判断不了某处改动是谁改的，停下来问，不猜。</li><li>改动文件都在允许范围内，没触碰禁改区和依赖文件。</li><li>不擅自 <code>push</code>、不擅自合并、不擅自删分支——这些由人决定。</li></ul><h3 id="提交信息" tabindex="-1">提交信息 <a class="header-anchor" href="#提交信息" aria-label="Permalink to “提交信息”">​</a></h3><p>写清「改了什么、为什么」，不说「update」「fix bugs」这类空话。一个提交对应一个能独立验收的子任务，不把所有改动堆成一次提交。</p><h3 id="diff-检查" tabindex="-1">diff 检查 <a class="header-anchor" href="#diff-检查" aria-label="Permalink to “diff 检查”">​</a></h3><p>提交前逐项看 diff：</p><ul><li>[ ] 改动文件都在允许范围，没有批量格式化无关文件。</li><li>[ ] 依赖文件（<code>pom.xml</code>、<code>package.json</code> 等）没有意外变更。</li><li>[ ] 没有硬编码特判、吞异常、放宽断言。</li><li>[ ] 没有删除或注释掉现有测试。</li><li>[ ] 没有留下调试打印、TODO、注释掉的分支。</li><li>[ ] 提交信息说清了改了什么、为什么。</li></ul><h3 id="保留用户改动的判断原则" tabindex="-1">保留用户改动的判断原则 <a class="header-anchor" href="#保留用户改动的判断原则" aria-label="Permalink to “保留用户改动的判断原则”">​</a></h3><p>宁可多问一句，不要覆盖用户写的东西。以下操作一律先确认：</p><ul><li>同一文件既有用户改动又有 AI 改动。</li><li>需要 <code>git checkout</code>、<code>git restore</code>、<code>git reset</code> 才能继续。</li><li>暂存区里有不是这次任务的内容。</li></ul><h2 id="可复制提示词" tabindex="-1">可复制提示词 <a class="header-anchor" href="#可复制提示词" aria-label="Permalink to “可复制提示词”">​</a></h2><details><summary><strong>提交前 Git 安全检查</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请对当前工作区做提交前检查，只输出检查结果，不执行任何 git 写操作（不 add、不 commit、不 checkout、不 reset、不 stash、不 push）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请先读取：git status、git diff、git diff --cached、最近几条 git log。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>检查项：</span></span>
<span class="line"><span>1. 有哪些用户已有的改动、未跟踪文件、暂存内容；和本次任务改动是否混在一起。</span></span>
<span class="line"><span>2. 改动文件是否都在允许范围，是否触及禁改区和依赖文件。</span></span>
<span class="line"><span>3. diff 里是否有硬编码、吞异常、放宽断言、删除测试、调试打印、遗留 TODO、批量格式化。</span></span>
<span class="line"><span>4. 提交信息是否说清「改了什么、为什么」。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出：</span></span>
<span class="line"><span>- 可以安全提交的文件清单。</span></span>
<span class="line"><span>- 需要人确认的冲突或疑点（逐条说明）。</span></span>
<span class="line"><span>- 建议的提交拆分方式（如果一个提交混了多件事）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不要替我做任何判断性合并，不要覆盖任何已有改动。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div></details><details><summary><strong>提交信息生成</strong></summary><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>请根据本次改动生成提交信息。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>改动：&lt;粘贴 git diff --stat 和关键 diff&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>要求：</span></span>
<span class="line"><span>1. 一句话说清改了什么，第二行说为什么。</span></span>
<span class="line"><span>2. 如果一次提交混了多件不相关的事，指出应该拆成几次，并给出各自的信息。</span></span>
<span class="line"><span>3. 不用「update」「fix bugs」「misc」这类空话。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>输出候选提交信息，我来选。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div></details><h2 id="验收要点" tabindex="-1">验收要点 <a class="header-anchor" href="#验收要点" aria-label="Permalink to “验收要点”">​</a></h2><ul><li>[ ] 提交前看过 status，用户已有改动被完整保留。</li><li>[ ] 没有擅自 checkout / reset / stash / push / 合并。</li><li>[ ] diff 检查全过，没有禁改内容混进来。</li><li>[ ] 提交信息说清改了什么、为什么。</li><li>[ ] 一个提交对应一个能独立验收的改动。</li></ul><p>变更的更细控制（范围、检查点、回滚）见 <a href="/my-vitepress-site/ai/productivity/dev-spec/03-quality/change-control.html">变更控制</a>。</p>`,21)])])}const u=a(l,[["render",p]]);export{h as __pageData,u as default};
